package nozle
import("context";"time")
// ProviderCapture describes a completed provider call. It contains usage metadata only.
type ProviderCapture struct { CustomerID,SubscriptionID,FeatureCode,Feature,CostMeterCode,Model,RequestID,TransactionID string; Latency time.Duration; Timestamp time.Time }
type OpenAIUsage struct { PromptTokens,CompletionTokens,CachedInputTokens,ReasoningTokens int }
type AnthropicUsage struct { InputTokens,CachedInputTokens,CacheWriteTokens,OutputTokens int }
type tokenCategory struct {name string;tokens int}
func(c *Client) captureProvider(ctx context.Context,provider string,p ProviderCapture,input,output int,categories []tokenCategory)error{if p.FeatureCode==""{p.FeatureCode="llm_tokens"};if p.TransactionID==""{p.TransactionID=generateUUID()};if p.Timestamp.IsZero(){p.Timestamp=time.Now().UTC()};properties:=map[string]any{"provider":provider,"model":p.Model,"input_tokens":input,"output_tokens":output,"latency_ms":p.Latency.Milliseconds()};if p.Feature!=""{properties["feature"]=p.Feature};if err:=c.Track(ctx,TrackParams{CustomerID:p.CustomerID,SubscriptionID:p.SubscriptionID,Event:p.FeatureCode,Metadata:properties,TransactionID:p.TransactionID,Timestamp:p.Timestamp.Format(time.RFC3339Nano)});err!=nil{return err};for _,cat:=range categories{if cat.tokens<=0||p.CostMeterCode==""{continue};ts:=float64(p.Timestamp.Unix());_,err:=c.TrackCostEvent(ctx,CostEventParams{CostEventID:p.TransactionID+":"+cat.name,CostMeterCode:p.CostMeterCode,ParentTransactionID:p.TransactionID,RequestID:p.RequestID,OperationKey:cat.name,Properties:map[string]any{"tokens":cat.tokens,"provider":provider,"model":p.Model,"type":cat.name},Timestamp:&ts});if err!=nil{return err}};return nil}
// CaptureOpenAIUsage records a completed OpenAI invocation and optional categorized cost events.
func(c *Client) CaptureOpenAIUsage(ctx context.Context,p ProviderCapture,u OpenAIUsage)error{cached:=min(max(u.CachedInputTokens,0),max(u.PromptTokens,0));reasoning:=min(max(u.ReasoningTokens,0),max(u.CompletionTokens,0));return c.captureProvider(ctx,"openai",p,u.PromptTokens,u.CompletionTokens,[]tokenCategory{{"input",u.PromptTokens-cached},{"cached_input",cached},{"output",u.CompletionTokens-reasoning},{"reasoning",reasoning}})}
// CaptureAnthropicUsage records a completed Anthropic invocation and optional categorized cost events.
func(c *Client) CaptureAnthropicUsage(ctx context.Context,p ProviderCapture,u AnthropicUsage)error{return c.captureProvider(ctx,"anthropic",p,u.InputTokens+u.CachedInputTokens+u.CacheWriteTokens,u.OutputTokens,[]tokenCategory{{"input",u.InputTokens},{"cached_input",u.CachedInputTokens},{"cache_write",u.CacheWriteTokens},{"output",u.OutputTokens}})}
